toolcall.title:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -NoProfile -Command "@'
import re
from pathlib import Path
failures = []
for file in sorted(Path('docs_v2/cn').glob('*.md')):
    text = file.read_text(encoding='utf-8')
    blocks = re.findall(r'"'```python'"\\n(.*?)"'```'"', text, re.S)
    for i, code in enumerate(blocks, 1):
        ns = {}
        try:
            exec(code, ns)
        except Exception as e:
            failures.append((str(file), i, type(e).__name__, str(e)))
print('python blocks checked:', sum(len(re.findall(r'"'```python'"\\n(.*?)"'```'"', p.read_text(encoding=\"utf-8\"), re.S)) for p in Path('docs_v2/cn').glob('*.md')))
print('failures:', failures)

missing = []
link_count = 0
for file in sorted(Path('docs_v2/cn').glob('*.md')):
    text = file.read_text(encoding='utf-8')
    for label, href in re.findall(r'\\[(["'^'"\\]]+)\\]\\((["'^)]+)'"\\)', text):
        link_count += 1
        if href.startswith(('http://', 'https://', '#')):
            continue
        target = (file.parent / href.split('#', 1)[0]).resolve()
        if not target.exists():
            missing.append((str(file), label, href))
print('links checked:', link_count)
print('missing:', missing)
'@ | python -"

